<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import api,{unwrap}from'@/api';import type{PageData,User}from'@/types';import{Plus,Refresh}from'@element-plus/icons-vue';import{ElMessage}from'element-plus'
const users=ref<User[]>([]),dialog=ref(false),keyword=ref(''),form=reactive({username:'',password:'123456',displayName:'',role:'STUDENT'})
async function load(){users.value=unwrap<PageData<User>>(await api.get('/users',{params:{pageSize:100,keyword:keyword.value}})).items}async function create(){await api.post('/users',form);ElMessage.success('用户已创建');dialog.value=false;Object.assign(form,{username:'',password:'123456',displayName:'',role:'STUDENT'});load()}async function toggle(row:User){const status=row.status==='ENABLED'?'DISABLED':'ENABLED';await api.patch(`/users/${row.id}/status`,{status});row.status=status;ElMessage.success('账号状态已更新')}onMounted(load)
</script><template><div><div class="page-title-row"><div><h2>用户与权限</h2><p>管理员与学生账号</p></div><div class="toolbar"><el-input v-model="keyword" placeholder="姓名或用户名" clearable @keyup.enter="load"/><el-button :icon="Refresh" @click="load">查询</el-button><el-button type="primary" :icon="Plus" @click="dialog=true">新增用户</el-button></div></div><section class="panel"><el-table :data="users" stripe><el-table-column prop="displayName" label="姓名" min-width="160"><template #default="{row}"><strong>{{row.displayName}}</strong><div class="username">@{{row.username}}</div></template></el-table-column><el-table-column label="角色" width="150"><template #default="{row}"><el-tag :type="row.role==='ADMIN'?'warning':'info'" effect="plain">{{row.role==='ADMIN'?'教师 / 管理员':'学生'}}</el-tag></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><span :class="['status-dot',row.status.toLowerCase()]">{{row.status==='ENABLED'?'启用':'停用'}}</span></template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="130"><template #default="{row}"><el-switch :model-value="row.status==='ENABLED'" @change="toggle(row)"/></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="新增用户" width="min(460px,92vw)"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="角色"><el-segmented v-model="form.role" :options="[{label:'学生',value:'STUDENT'},{label:'教师 / 管理员',value:'ADMIN'}]"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog></div></template><style scoped>.username{font-size:11px;color:var(--muted);margin-top:4px}.status-dot{font-size:12px;color:var(--green)}.status-dot:before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;margin-right:6px}.status-dot.disabled{color:#999}</style>

